// Scratch blast-radius probe: for every layout git itself accepts, does the
// canonical resolver yield the same worktree ID that hooks record today?
func TestBlastRadiusWorktreeIDParity(t *testing.T) {
	for _, k := range []string{"GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR", "GIT_INDEX_FILE", "GIT_CEILING_DIRECTORIES"} {
		t.Setenv(k, "")
		os.Unsetenv(k)
	}
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("GIT_CONFIG_GLOBAL", filepath.Join(home, "gitconfig"))
	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")

	tmp, err := filepath.EvalSymlinks(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	git := func(dir string, args ...string) string {
		t.Helper()
		full := append([]string{"-c", "user.name=t", "-c", "user.email=t@e", "-c", "protocol.file.allow=always", "-c", "init.defaultBranch=main"}, args...)
		cmd := exec.Command("git", full...)
		cmd.Dir = dir
		out, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("git %v in %s: %v\n%s", args, dir, err, out)
		}
		return strings.TrimSpace(string(out))
	}
	seed := func(dir string) {
		t.Helper()
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatal(err)
		}
		git(dir, "init", "-q")
		if err := os.WriteFile(filepath.Join(dir, "f"), []byte("x\n"), 0o644); err != nil {
			t.Fatal(err)
		}
		git(dir, "add", "f")
		git(dir, "commit", "-qm", "init")
	}

	type layout struct{ name, root string }
	var layouts []layout
	add := func(name, root string) { layouts = append(layouts, layout{name, root}) }

	main := filepath.Join(tmp, "main")
	seed(main)
	add("main worktree", main)

	git(main, "worktree", "add", "-q", filepath.Join(tmp, "a", "wt"))
	add("linked worktree", filepath.Join(tmp, "a", "wt"))
	git(main, "worktree", "add", "-q", filepath.Join(tmp, "b", "wt"))
	add("linked worktree, duplicate basename", filepath.Join(tmp, "b", "wt"))
	git(main, "worktree", "add", "-q", "--relative-paths", filepath.Join(tmp, "rel"))
	add("linked worktree, relative paths", filepath.Join(tmp, "rel"))

	git(main, "worktree", "add", "-q", filepath.Join(tmp, "tomove"))
	if err := os.Rename(filepath.Join(tmp, "tomove"), filepath.Join(tmp, "moved")); err != nil {
		t.Fatal(err)
	}
	add("linked worktree moved without repair", filepath.Join(tmp, "moved"))

	if err := os.Symlink(filepath.Join(tmp, "a", "wt"), filepath.Join(tmp, "wtlink")); err != nil {
		t.Fatal(err)
	}
	add("linked worktree through symlinked path", filepath.Join(tmp, "wtlink"))

	bareProj := filepath.Join(tmp, "bareproj")
	if err := os.MkdirAll(bareProj, 0o755); err != nil {
		t.Fatal(err)
	}
	git(bareProj, "clone", "-q", "--bare", main, ".bare")
	git(bareProj, "--git-dir=.bare", "worktree", "add", "-q", "dev")
	add(".bare linked worktree", filepath.Join(bareProj, "dev"))

	git(tmp, "clone", "-q", "--bare", main, "storage")
	git(tmp, "--git-dir", filepath.Join(tmp, "storage"), "worktree", "add", "-q", filepath.Join(tmp, "target"))
	add("bare repo named storage, linked worktree (new)", filepath.Join(tmp, "target"))

	sep := filepath.Join(tmp, "sepwork")
	git(tmp, "init", "-q", "--separate-git-dir", filepath.Join(tmp, "sepgit"), sep)
	add("--separate-git-dir main worktree (new)", sep)

	subSrc := filepath.Join(tmp, "subsrc")
	seed(subSrc)
	super := filepath.Join(tmp, "super")
	seed(super)
	git(super, "submodule", "add", "-q", subSrc, "sub")
	git(super, "commit", "-qm", "add sub")
	add("submodule", filepath.Join(super, "sub"))
	git(filepath.Join(super, "sub"), "worktree", "add", "-q", filepath.Join(tmp, "subwt"))
	add("submodule's linked worktree", filepath.Join(tmp, "subwt"))
	git(super, "worktree", "add", "-q", filepath.Join(tmp, "superwt"))
	git(filepath.Join(tmp, "superwt"), "submodule", "update", "-q", "--init")
	add("submodule inside superproject's linked worktree", filepath.Join(tmp, "superwt", "sub"))

	odd := filepath.Join(tmp, "odd", ".git", "worktrees", "x", "proj")
	seed(odd)
	git(odd, "worktree", "add", "-q", filepath.Join(tmp, "oddwt"))
	add("repo under a path containing .git/worktrees/", filepath.Join(tmp, "oddwt"))

	for _, l := range layouts {
		gitOK := exec.Command("git", "-C", l.root, "rev-parse", "--git-dir").Run() == nil
		oldID, oldErr := paths.GetWorktreeID(l.root)
		md, newErr := gitrepo.ResolveWorktreeMetadata(l.root)
		verdict := "same"
		switch {
		case oldErr != nil && newErr != nil:
			verdict = "both fail"
		case oldErr != nil:
			verdict = "NEW: old fails, resolver works"
		case newErr != nil:
			verdict = "REGRESSION: resolver fails"
		case oldID != md.WorktreeID:
			verdict = "DIFFERENT ID"
		}
		t.Logf("%-50s git=%-5v old=%-28q new=%-10q %s", l.name, gitOK, short(oldID, oldErr), md.WorktreeID, verdict)
		if gitOK && oldErr == nil && (newErr != nil || oldID != md.WorktreeID) {
			t.Errorf("%s: hooks record %q today, resolver gives %q (err %v)", l.name, oldID, md.WorktreeID, newErr)
		}
	}
}

