// Scratch probe: under exported repo selectors, which repository does each
// piece of `entire import` actually use?
func TestProbeImportRepositorySelection(t *testing.T) {
	ctx := context.Background()
	commit := func(t *testing.T, dir, msg string) string {
		testutil.InitRepo(t, dir)
		testutil.WriteFile(t, dir, "f", msg)
		testutil.GitAdd(t, dir, "f")
		testutil.GitCommit(t, dir, msg)
		return testutil.GetHeadHash(t, dir)
	}

	t.Run("redirect: worktree has its own .git, GIT_DIR names another repo", func(t *testing.T) {
		tmp, _ := filepath.EvalSymlinks(t.TempDir())
		a, b := filepath.Join(tmp, "a"), filepath.Join(tmp, "b")
		headA, headB := commit(t, a, "A"), commit(t, b, "B")
		t.Chdir(a)
		t.Setenv("GIT_DIR", filepath.Join(b, ".git"))
		paths.ClearWorktreeRootCache()

		root, err := paths.WorktreeRoot(ctx)
		t.Logf("paths.WorktreeRoot          -> %s (err %v)", rel(tmp, root), err)
		repo, err := strategy.OpenRepository(ctx)
		if err != nil {
			t.Logf("strategy.OpenRepository     -> error: %v", err)
		} else {
			head, _ := repo.Head()
			which := "?"
			switch head.Hash().String() {
			case headA:
				which = "A (local .git)"
			case headB:
				which = "B (GIT_DIR)"
			}
			t.Logf("strategy.OpenRepository     -> HEAD of %s  [checkpoints are written here]", which)
			repo.Close()
		}
		store, err := session.NewStateStoreForWorktree(ctx, root)
		t.Logf("NewStateStoreForWorktree    -> %s (err %v)  [current PR]", storeDir(tmp, store), err)
		envAware, err := gitdir.CommonDirForWorktree(ctx, root)
		t.Logf("gitdir.CommonDirForWorktree -> %s (err %v)  [main / approved fix 1]", rel(tmp, envAware), err)
		md, err := gitrepo.ResolveWorktreeMetadata(root)
		t.Logf("ResolveWorktreeMetadata     -> %s (err %v)", rel(tmp, md.CommonDir), err)
	})

	t.Run("split: GIT_DIR and GIT_WORK_TREE, work tree has no .git", func(t *testing.T) {
		tmp, _ := filepath.EvalSymlinks(t.TempDir())
		work, store := filepath.Join(tmp, "work"), filepath.Join(tmp, "store")
		commit(t, work, "W")
		if err := os.MkdirAll(store, 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.Rename(filepath.Join(work, ".git"), filepath.Join(store, "repo.git")); err != nil {
			t.Fatal(err)
		}
		t.Chdir(work)
		t.Setenv("GIT_DIR", filepath.Join(store, "repo.git"))
		t.Setenv("GIT_WORK_TREE", work)
		paths.ClearWorktreeRootCache()

		root, err := paths.WorktreeRoot(ctx)
		t.Logf("paths.WorktreeRoot          -> %s (err %v)", rel(tmp, root), err)
		repo, err := strategy.OpenRepository(ctx)
		if err != nil {
			t.Logf("strategy.OpenRepository     -> error: %v  [import stops here]", err)
		} else {
			t.Logf("strategy.OpenRepository     -> opened")
			repo.Close()
		}
		st, err := session.NewStateStoreForWorktree(ctx, root)
		t.Logf("NewStateStoreForWorktree    -> %s (err %v)  [current PR]", storeDir(tmp, st), err)
		envAware, err := gitdir.CommonDirForWorktree(ctx, root)
		t.Logf("gitdir.CommonDirForWorktree -> %s (err %v)  [main / approved fix 1]", rel(tmp, envAware), err)
	})
}

func rel(base, p string) string {
	if p == "" {
		return `""`
	}
	if r, err := filepath.Rel(base, p); err == nil {
		return r
	}
	return p
}

func storeDir(base string, s *session.StateStore) string {
	if s == nil {
		return "<nil>"
	}
	return rel(base, s.Dir())
}

