// The import command opens its repository with strategy.OpenRepository, which
// reads the worktree's own .git even when GIT_DIR names another repository, and
// writes checkpoints there. The imported session state must land in that same
// repository, or `entire session list` cannot see sessions whose checkpoints exist.
func TestRun_SessionStateFollowsCheckpointRepositoryUnderExportedGitDir(t *testing.T) {
	tmp := t.TempDir()
	local, other := filepath.Join(tmp, "local"), filepath.Join(tmp, "other")
	for _, dir := range []string{local, other} {
		testutil.InitRepo(t, dir)
		testutil.WriteFile(t, dir, "f.txt", dir)
		testutil.GitAdd(t, dir, "f.txt")
		testutil.GitCommit(t, dir, "init")
	}
	transcript := filepath.Join(local, "session.jsonl")
	if err := os.WriteFile(transcript, []byte(`{"type":"user"}`+"\n"), 0o600); err != nil {
		t.Fatalf("write transcript: %v", err)
	}
	t.Chdir(local)
	t.Setenv("GIT_DIR", filepath.Join(other, ".git"))
	paths.ClearWorktreeRootCache()
	t.Cleanup(paths.ClearWorktreeRootCache)

	ctx := context.Background()
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		t.Fatalf("WorktreeRoot: %v", err)
	}
	repo, err := strategy.OpenRepository(ctx)
	if err != nil {
		t.Fatalf("OpenRepository: %v", err)
	}
	defer repo.Close()
	if got, want := repoHeadSHA(t, repo), testutil.GetHeadHash(t, local); got != want {
		t.Fatalf("checkpoint repository HEAD = %s, want the local repository's %s", got, want)
	}

	const sid = "claude-exported-git-dir-session"
	imp := runFakeImporter{
		files: []SessionFile{{Path: transcript, SessionID: sid}},
		turns: []Turn{{UUID: "a", Prompt: "hello", CreatedAt: time.Now().Add(-time.Hour)}},
	}
	if _, err := Run(ctx, repo, imp, Options{LinkCommitSHA: repoHeadSHA(t, repo), RepoRoot: repoRoot, Now: time.Now()}); err != nil {
		t.Fatalf("Run: %v", err)
	}

	for _, tc := range []struct {
		repo      string
		wantState bool
	}{{local, true}, {other, false}} {
		store := session.NewStateStoreWithDir(filepath.Join(tc.repo, ".git", session.SessionStateDirName))
		st, err := store.Load(ctx, sid)
		if err != nil {
			t.Fatalf("load state from %s: %v", tc.repo, err)
		}
		if got := st != nil; got != tc.wantState {
			t.Errorf("session state in %s = %v, want %v", filepath.Base(tc.repo), got, tc.wantState)
		}
	}
}

